sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var appSysId = tr.sys_id.toString();

    // ── 1. Gather candidate data (dot-walk from trigger) ──
    var candidateProfile = {
        skills: tr.candidate.skills.toString(),
        years_experience: tr.candidate.years_experience.toString(),
        relevant_projects: tr.candidate.relevant_projects.toString(),
        certifications: tr.candidate.certifications.toString(),
        education_level: tr.candidate.education_level.toString()
    };

    // ── 2. Gather requisition criteria (dot-walk from trigger) ──
    var reqSkills = tr.requisition.required_skills.toString();
    var reqExp = tr.requisition.experience_years_required.toString();
    var reqEdu = tr.requisition.education_required.toString();
    var reqSysId = tr.requisition.toString(); // sys_id of the requisition
    var candSysId = tr.candidate.toString();  // sys_id of the candidate

    // ── 3. Run the deterministic scorer ──
    var scorer = new x_snc_aegis.AEGISResumeScorer();
    var result = scorer.scoreCandidate(candidateProfile, reqSkills, reqExp, reqEdu);

    // ── 4. Identify transferable skills ──
    // Transferable = candidate skills NOT in required list but still valuable
    var candidateSkillsArr = (candidateProfile.skills || '').split(',').map(function(s) { return s.trim(); });
    var matchedArr = (result.matched_skills || '').split(',').map(function(s) { return s.trim().toLowerCase(); });
    var missingArr = (result.missing_skills || '').split(',').map(function(s) { return s.trim().toLowerCase(); });
    var transferable = [];
    for (var i = 0; i < candidateSkillsArr.length; i++) {
        var cs = candidateSkillsArr[i].trim();
        if (cs && matchedArr.indexOf(cs.toLowerCase()) === -1) {
            transferable.push(cs);
        }
    }

    // ── 5. Create Screening Result record ──
    var sr = new GlideRecord('x_snc_aegis_screening_result');
    sr.initialize();
    sr.setValue('application', appSysId);
    sr.setValue('candidate', candSysId);
    sr.setValue('requisition', reqSysId);
    sr.setValue('fit_score', result.fit_score);
    sr.setValue('skills_score', result.skills_score);
    sr.setValue('experience_score', result.experience_score);
    sr.setValue('projects_score', result.projects_score);
    sr.setValue('certifications_score', result.certifications_score);
    sr.setValue('education_score', result.education_score);
    sr.setValue('matched_skills', result.matched_skills);
    sr.setValue('missing_skills', result.missing_skills);
    sr.setValue('transferable_skills', transferable.join(', '));
    sr.setValue('explanation', result.explanation);
    sr.setValue('scoring_agent', 'AEGISResumeScorer (Deterministic)');
    sr.setValue('screened_at', new GlideDateTime());
    sr.setValue('screening_status', 'COMPLETED');
    sr.setValue('is_blind_scored', true);

    var srSysId = sr.insert();

    // ── 6. Update Application ──
    var appGr = new GlideRecord('x_snc_aegis_application');
    if (appGr.get(appSysId)) {
        appGr.setValue('screening_status', 'COMPLETED');
        appGr.setValue('screening_completed_at', new GlideDateTime());
        appGr.update();
    }

    // ── 7. Log to AI Decision Log ──
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Resume Intelligence',
        'RESUME_SCREEN',
        appSysId,
        reqSysId,
        'Candidate: ' + tr.candidate.full_name.toString() +
            ' | Skills: ' + candidateProfile.skills.substring(0, 150) +
            ' | Exp: ' + candidateProfile.years_experience + 'yr',
        'Fit Score: ' + result.fit_score + '/100 | ' + result.explanation.substring(0, 300),
        result.fit_score / 100,
        'Blind scoring (no PII); Deterministic 6-factor weighted model; is_blind_scored=true'
    );

    // ── 8. Outputs ──
    outputs.screening_result_sys_id = srSysId;
    outputs.fit_score = result.fit_score;

})(inputs, outputs);

